#: 2000 consecutive bit patterns starting at the smallest positive normal double.
_NUM_SERIAL = 2000
_SMALLEST_NORMAL_BITS = 0x0010000000000000


def _bits_to_float(bits: int) -> float:
    return struct.unpack("<d", struct.pack("<Q", bits))[0]


def _float_to_bits(value: float) -> int:
    return struct.unpack("<Q", struct.pack("<d", value))[0]


def float_sequence() -> Iterator[float]:
    """Yield the upstream sequence of doubles, forever."""
    index = 0
    block = bytes(32)
    data = b""
    while True:
        if index < len(_STATIC):
            value = _bits_to_float(_STATIC[index])
        elif index < len(_STATIC) + _NUM_SERIAL:
            value = _bits_to_float(_SMALLEST_NORMAL_BITS + (index - len(_STATIC)))
        else:
            value = 0.0
            while value == 0.0 or math.isnan(value) or math.isinf(value):
                if not data:
                    block = hashlib.sha256(block).digest()
                    data = block
                value = _bits_to_float(int.from_bytes(data[:8], "little"))
                data = data[8:]
        index += 1
        yield value


def generate_lines(count: int, serialise: Callable[[float], str]) -> Iterator[bytes]:
    """Yield ``count`` lines of the ES6 test file, formatting numbers with *serialise*.

    *serialise* is passed in rather than imported so this module stays usable as a plain
    oracle: the test hands it :func:`trappoint_jcs.canon_v1.es6_number`, and any
    third-party implementation can be checked the same way.
    """
    sequence = float_sequence()
    for _ in range(count):
        value = next(sequence)
        yield f"{_float_to_bits(value):x},{serialise(value)}\n".encode()
